from __future__ import annotations

import base64
import gzip
import hashlib
import json
import sqlite3
from pathlib import Path


BASE_DIR = Path(__file__).resolve().parent
DATABASE_PATH = BASE_DIR / "database" / "footwin_sports.db"

MIGRATION_ID = "0009_seed_fra1_ita1_ger1_frozen"
DESCRIPTION = (
    "Seed idempotente de dataset, equipas, calendários FRA1/ITA1/GER1 "
    "e PRE_MATCH congelados já publicados em 2026/27"
)

EXPECTED_DATASETS = 1
EXPECTED_TEAMS = 56
EXPECTED_MATCHES = 992
EXPECTED_PREDICTIONS = 695
EXPECTED_PAYLOAD_SHA256 = "b12b597073a22a7ceffd964a80513c873ed05f0e13b5e125aa21bd099d4422ff"

PAYLOAD_B64 = """"""


def load_payload() -> dict:
    compressed = base64.b64decode(
        PAYLOAD_B64.encode("ascii")
    )
    raw = gzip.decompress(compressed)

    actual_hash = hashlib.sha256(raw).hexdigest()

    if actual_hash != EXPECTED_PAYLOAD_SHA256:
        raise RuntimeError(
            "Payload 0009 corrompido: hash inesperado."
        )

    payload = json.loads(
        raw.decode("utf-8")
    )

    expected_counts = {
        "dataset_versions": EXPECTED_DATASETS,
        "teams": EXPECTED_TEAMS,
        "matches": EXPECTED_MATCHES,
        "predictions": EXPECTED_PREDICTIONS,
    }

    actual_counts = {
        key: len(payload[key])
        for key in expected_counts
    }

    if actual_counts != expected_counts:
        raise RuntimeError(
            "Contagens inesperadas no payload 0009: "
            f"{actual_counts}"
        )

    return payload


def insert_missing_row(
    connection: sqlite3.Connection,
    table: str,
    pk_name: str,
    row: dict,
) -> bool:
    existing = connection.execute(
        f"SELECT 1 FROM {table} WHERE {pk_name} = ?",
        (row[pk_name],),
    ).fetchone()

    if existing is not None:
        return False

    columns = list(row)
    placeholders = ", ".join(
        "?" for _ in columns
    )
    column_sql = ", ".join(columns)

    connection.execute(
        f"""
        INSERT INTO {table} (
            {column_sql}
        )
        VALUES ({placeholders})
        """,
        tuple(row[column] for column in columns),
    )

    return True


def validate_seeded_predictions(
    connection: sqlite3.Connection,
    rows: list[dict],
) -> None:
    for row in rows:
        existing = connection.execute(
            """
            SELECT *
            FROM match_predictions
            WHERE prediction_id = ?
            """,
            (row["prediction_id"],),
        ).fetchone()

        if existing is None:
            raise RuntimeError(
                "PRE_MATCH congelado em falta após 0009: "
                f"{row['prediction_id']}"
            )

        existing_dict = dict(existing)

        if existing_dict != row:
            raise RuntimeError(
                "Colisão num PRE_MATCH congelado: "
                f"{row['prediction_id']}"
            )


def main() -> int:
    payload = load_payload()

    connection = sqlite3.connect(
        DATABASE_PATH
    )
    connection.row_factory = sqlite3.Row

    inserted_datasets = 0
    inserted_teams = 0
    inserted_matches = 0
    inserted_predictions = 0

    try:
        connection.execute(
            "PRAGMA foreign_keys = ON"
        )
        connection.execute(
            "BEGIN IMMEDIATE"
        )

        for row in payload["dataset_versions"]:
            if insert_missing_row(
                connection=connection,
                table="dataset_versions",
                pk_name="dataset_version",
                row=row,
            ):
                inserted_datasets += 1

        for row in payload["teams"]:
            if insert_missing_row(
                connection=connection,
                table="teams",
                pk_name="team_id",
                row=row,
            ):
                inserted_teams += 1

        for row in payload["matches"]:
            if insert_missing_row(
                connection=connection,
                table="matches",
                pk_name="match_id",
                row=row,
            ):
                inserted_matches += 1

        for row in payload["predictions"]:
            if insert_missing_row(
                connection=connection,
                table="match_predictions",
                pk_name="prediction_id",
                row=row,
            ):
                inserted_predictions += 1

        validate_seeded_predictions(
            connection,
            payload["predictions"],
        )

        expected_matches = {
            "FRA1": 306,
            "ITA1": 380,
            "GER1": 306,
        }

        minimum_pre_match = {
            "FRA1": 306,
            "ITA1": 380,
            "GER1": 9,
        }

        counts = {}

        for league_id in (
            "FRA1",
            "ITA1",
            "GER1",
        ):
            teams = connection.execute(
                """
                SELECT COUNT(*)
                FROM teams
                WHERE league_id = ?
                  AND season_label = '2026/27'
                """,
                (league_id,),
            ).fetchone()[0]

            matches = connection.execute(
                """
                SELECT COUNT(*)
                FROM matches
                WHERE league_id = ?
                  AND season_label = '2026/27'
                """,
                (league_id,),
            ).fetchone()[0]

            pre_match = connection.execute(
                """
                SELECT COUNT(*)
                FROM match_predictions AS p
                JOIN matches AS m
                  ON m.match_id = p.match_id
                WHERE m.league_id = ?
                  AND m.season_label = '2026/27'
                  AND p.prediction_stage = 'PRE_MATCH'
                """,
                (league_id,),
            ).fetchone()[0]

            counts[league_id] = {
                "teams": int(teams),
                "matches": int(matches),
                "pre_match": int(pre_match),
            }

            if int(matches) != expected_matches[league_id]:
                raise RuntimeError(
                    "Quantidade de jogos inesperada após 0009: "
                    f"{league_id}={matches}"
                )

            if int(pre_match) < minimum_pre_match[league_id]:
                raise RuntimeError(
                    "Quantidade mínima de PRE_MATCH não atingida: "
                    f"{league_id}={pre_match}"
                )

        expected_teams = {
            "FRA1": 18,
            "ITA1": 20,
            "GER1": 18,
        }

        for league_id, expected in expected_teams.items():
            if counts[league_id]["teams"] != expected:
                raise RuntimeError(
                    "Quantidade de equipas inesperada após 0009: "
                    f"{league_id}={counts[league_id]['teams']}"
                )

        fk_errors = list(
            connection.execute(
                "PRAGMA foreign_key_check"
            )
        )

        if fk_errors:
            raise RuntimeError(
                "Foreign keys inválidas após 0009: "
                f"{fk_errors[:10]}"
            )

        connection.commit()

    except Exception:
        connection.rollback()
        raise

    finally:
        connection.close()

    print(
        "0009 OK | "
        f"inserted_datasets={inserted_datasets} | "
        f"inserted_teams={inserted_teams} | "
        f"inserted_matches={inserted_matches} | "
        f"inserted_predictions={inserted_predictions}"
    )

    for league_id, values in counts.items():
        print(
            league_id,
            "| teams =",
            values["teams"],
            "| matches =",
            values["matches"],
            "| PRE_MATCH =",
            values["pre_match"],
        )

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
